def convert_base(s, from_base, to_base):
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    val = int(s, from_base)
    if val == 0:
        return "0"
    neg = val < 0
    val = abs(val)
    out = []
    while val:
        out.append(digits[val % to_base])
        val //= to_base
    if neg:
        out.append('-')
    return ''.join(reversed(out))

