def is_semiprime(n):
    if n < 4:
        return False
    count = 0
    temp = n
    d = 2
    while d * d <= temp:
        while temp % d == 0:
            temp //= d
            count += 1
            if count > 2:
                return False
        d += 1
    if temp > 1:
        count += 1
    return count == 2

def is_squarefree(n):
    n = abs(n)
    if n == 0:
        return False
    d = 2
    while d * d <= n:
        if n % (d * d) == 0:
            return False
        d += 1
    return True
